import backtrader as bt


class MA200ExitStrategy(bt.Strategy):
    params = dict(
        sma_period=200,
        position_pct=0.01,
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_period
        )
        self.crossover = bt.indicators.CrossOver(self.data.close, self.sma)
        self.order = None

    def notify_order(self, order):
        if order.status in (order.Completed, order.Canceled, order.Margin, order.Rejected):
            self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.crossover > 0:
                size = int((self.broker.getvalue() * self.p.position_pct) / self.data.close[0])
                if size > 0:
                    self.order = self.buy(size=size)
        else:
            if self.crossover < 0:
                self.order = self.close()
